I'll help you iteratively improve the CUDA kernel for matrix multiplication. Let's start with the first iteration.

### Iteration 1: Basic Matrix Multiplication Kernel
We'll implement a simple CUDA kernel for matrix multiplication without optimizations. Each thread will compute one element of the output matrix.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; k++) {
            sum += A[row * K + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_forward_cuda(
    torch::Tensor A,
    torch::Tensor B
) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 threads(16, 16);
    dim3 blocks((N + threads.x - 1) / threads.x, (M + threads.y - 1) / threads.y);

    matmul_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    return C;
}
"""

cpp_source = "torch::Tensor matmul_forward_cuda(torch::Tensor A, torch::Tensor B);"

matmul_extension = load_inline(
    name="matmul_extension",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_forward_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(128, 128))

    def forward(self, x):
        return matmul_extension.matmul_forward_cuda(x, self.weight)
```

