### Iteration 2: Shared Memory Optimization
Now let's optimize by using shared memory to reduce global memory accesses. We'll implement tiling with 16x16 blocks:

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K
) {
    // Shared memory for tiles of A and B
    __shared__ float A_tile[16][16];
    __shared__ float B_tile[16][16];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * blockDim.y + ty;
    int col = blockIdx.x * blockDim.x + tx;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (K + 15) / 16; t++) {
        // Load tile of A into shared memory
        int A_col = t * 16 + tx;
        if (row < M && A_col < K) {
            A_tile[ty][tx] = A[row * K + A_col];
        } else {
            A_tile[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory
        int B_row = t * 16 + ty;
        if (B_row < K && col < N) {
            B_tile[ty][tx] = B[B_row * N + col];
        } else {
            B_tile[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum for this tile
        for (int k = 0; k < 16; k++) {
            sum += A_tile[ty][k] * B_tile[k][tx];
        }

        __syncthreads();
    }

    // Write result to output
    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_forward_cuda(
    torch::Tensor A,
    torch::Tensor B
) {
    // Check tensor dimensions
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions mismatch");

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 threads(16, 16);
    dim3 blocks((N + threads.x - 1) / threads.x, (M + threads.y - 1) / threads.y);

    matmul_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    // Check for CUDA errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        TORCH_CHECK(false, "CUDA kernel failed: ", cudaGetErrorString(err));
    }

    return C;
}
"""

