The shared memory version is slightly slower (2.52 ms vs 2.5 ms). This might be due to the overhead of shared memory synchronization. Let's try to optimize further by increasing the tile size and using register blocking.

### Iteration 3: Register Blocking and Larger Tile Size
We'll use 32x32 thread blocks and have each thread compute a 4x4 tile of the output matrix:

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 4

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K
) {
    // Shared memory for tiles of A and B
    __shared__ float A_tile[TILE_SIZE][TILE_SIZE];
    __shared__ float B_tile[TILE_SIZE][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Thread block position
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // Each thread computes BLOCK_SIZE x BLOCK_SIZE elements of C
    float Csub[BLOCK_SIZE][BLOCK_SIZE] = {{0}};

    // Loop over tiles
    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile of A into shared memory
        int A_row = blockRow * TILE_SIZE + ty;
        int A_col = t * TILE_SIZE + tx;
        if (A_row < M && A_col < K) {
            A_tile[ty][tx] = A[A_row * K + A_col];
        } else {
            A_tile[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory
        int B_row = t * TILE_SIZE + ty;
        int B_col = blockCol * TILE_SIZE + tx;
        if (B_row < K && B_col < N) {
            B_tile[ty][tx] = B[B_row * N + B_col];
        } else {
            B_tile[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum for this tile
        for (int k = 0; k < TILE_SIZE; k++) {
            for (int i = 0; i < BLOCK_SIZE; i++) {
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    Csub[i][j] += A_tile[i * TILE_SIZE / BLOCK_SIZE + ty][k] * 
                                  B_tile[k][j * TILE_SIZE / BLOCK_SIZE + tx];
                }
            }
        }

        __syncthreads();
    }

    // Write result to output
    for (int i = 0; i < BLOCK_SIZE; i++) {
        for (int j = 0; j < BLOCK_SIZE; j++) {
            int row = blockRow * TILE_SIZE + i * TILE_SIZE / BLOCK_SIZE + ty;
            int col = blockCol * TILE_SIZE + j * TILE_SIZE / BLOCK_SIZE + tx;
            if (row < M && col < N) {
                C[row * N + col] = Csub[i][j];
            }
        }
    }
}

torch::Tensor matmul_forward_cuda(
    torch::Tensor A,
    torch::Tensor B
) {
    // Check tensor dimensions
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions mismatch");

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 threads(TILE_SIZE / BLOCK_SIZE, TILE_SIZE / BLOCK_SIZE);
    dim3 blocks((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    // Check for CUDA errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        TORCH_CHECK(false, "CUDA kernel failed: ", cudaGetErrorString(err));
    }

    return C;
}
"""

