We'll use warp-level primitives to optimize the matrix multiplication:

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 8

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K
) {
    // Warp-level matrix multiply
    const int warp_size = 32;
    const int warp_row = threadIdx.y;
    const int warp_col = threadIdx.x;

    // Block position
    int block_row = blockIdx.y * TILE_SIZE;
    int block_col = blockIdx.x * TILE_SIZE;

    // Thread position within warp
    int row_in_warp = warp_row % BLOCK_SIZE;
    int col_in_warp = warp_col % BLOCK_SIZE;
    int warp_id = warp_row / BLOCK_SIZE;

    // Each warp computes a 32x32 tile
    float accum = 0.0f;

    // Loop over K dimension
    for (int k = 0; k < K; k++) {
        // Load elements
        float a_val = (block_row + warp_row < M && k < K) ? 
                      A[(block_row + warp_row) * K + k] : 0.0f;
        float b_val = (k < K && block_col + warp_col < N) ? 
                      B[k * N + (block_col + warp_col)] : 0.0f;

        // Warp-level reduction
        for (int offset = 16; offset > 0; offset /= 2) {
            a_val += __shfl_down_sync(0xffffffff, a_val, offset);
            b_val += __shfl_down_sync(0xffffffff, b_val, offset);
        }

        // Accumulate
        accum += a_val * b_val;
    }

    // Write result
    if (block_row + warp_row < M && block_col + warp_col < N) {
        C[(block_row + warp_row) * N + (block_col + warp_col)] = accum;
    }
}

